import{z as B,x as c,o as l,c as p,q as r,j as i,D as t,d as o,s as n,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"片上网络 NoC","description":"","frontmatter":{"title":"片上网络 NoC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/noc-topology.md","filePath":"cs/noc-topology.md","lastUpdated":1791413859000}'),d={name:"cs/noc-topology.md"};function A(m,a,h,f,C,D){const s=c("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="片上网络-noc" tabindex="-1">片上网络 NoC <a class="header-anchor" href="#片上网络-noc" aria-label="Permalink to &quot;片上网络 NoC&quot;">​</a></h1><div class="epigraph"><p>核、cache slice 与内存控制器不再共享一条广播总线；包在路由器之间跳，带宽随链路数涨，延迟变成跳数与拥塞。</p><footer>—— 据 Dally and Towles, Principles and Practices of Interconnection Networks 整理</footer></div><p><a href="/cs/heterogeneous-soc">上一课</a> 把多种核放在同一硅上。<a href="/cs/directory-scalability">目录</a> 已经要求点对点。十几个以上节点时，总线与交叉开关的线长、仲裁都不可接受。本课不重讲 big.LITTLE 迁移。缺口是 <strong>NoC：片上包交换网络作为一致性事务的载体。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>广播窥探假设人人听见。交叉开关面积 \\(O(n^2)\\)。缺口不是再加一个 Forward 态，而是<strong>用路由器 + 链路连接 tile：每 tile 有核、L1、L2 slice、路由器。一致性消息、DMA、I/O 都变成 flit。</strong></p><p><span class="marginnote">Dally–Towles：互连是一等公民。片上与片间原理相同，只是延迟与缓冲预算不同。拓扑下一课才选 mesh 或 fat-tree。</span></p><p><span class="marginnote">数字实例：\\(8\\times8\\) 网格、每跳约 3 ns，对角请求单程 14 跳、约 40 ns，还不含排队。核数从 4 涨到 64 时，NoC 的链路数近似线性涨、总带宽跟着涨；总线带宽则原地踏步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个 tile 一个路由器：输入缓冲、路由计算、虚通道、开关分配、链路口。消息：读请求、转发、作废、ack、数据。 homing：地址哈希到 slice，即目录 home。QoS：不同虚通道给延迟敏感的一致性 ack 与批量 DMA。</p><p><span class="marginnote">直觉类比：NoC 把片内互连从「全村大喇叭」（总线）换成「邮政网」——每个 tile 是带邮局的住户，消息装成小包裹按地址逐站转寄；包裹多了会堵（拥塞），路程有远近（跳数）。</span></p>',10)),(l(),i(E,null,{default:t(()=>[n(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORE%5B%22%E6%A0%B8%20%2F%20L1%22%5D%20--%3E%20R%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%22%5D%0A%20%20R%20--%3E%20LNK%5B%22%E9%93%BE%E8%B7%AF%E5%88%B0%E9%82%BB%20tile%22%5D%0A%20%20R%20--%3E%20SLICE%5B%22%E6%9C%AC%20tile%20%E7%9A%84%20L2%2F%E7%9B%AE%E5%BD%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[e("a",{href:"/cs/mlp-memory-parallelism"},"MLP"),o(" 的 miss 现在排队在 NoC 里；热点 slice 造成热树。与 "),e("a",{href:"/cs/fence-cost"},"fence"),o("：fence 等待的「可见」包括包到达 home 并完成 inv ack，跳数进入临界区代价。功耗：连线与路由器缓冲是多核能耗大头之一。")],-1)),a[5]||(a[5]=e("p",null,"包优先级：作废 ack 比批量 DMA 更延迟敏感，否则锁的临界区被大块拷贝堵住。这就是虚通道与 QoS 在片上出现的原因，具体拓扑下一课才选。",-1)),(l(),i(E,null,{default:t(()=>[n(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20C%5B%22tile%20A%EF%BC%9A%E6%A0%B8%E5%8F%91%E8%AF%BB%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20H1%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E9%80%90%E8%B7%B3%E8%BD%AC%E5%8F%91%22%5D%0A%20%20H1%20--%3E%20HM%5B%22home%20tile%EF%BC%9A%E6%9F%A5%E7%9B%AE%E5%BD%95%E4%B8%8E%20L2%20slice%22%5D%0A%20%20HM%20--%3E%20INV%5B%22%E5%BF%85%E8%A6%81%E6%97%B6%E5%8F%91%E4%BD%9C%E5%BA%9F%20%2F%20%E8%BD%AC%E5%8F%91%E5%B9%B6%E6%94%B6%20ack%22%5D%0A%20%20INV%20--%3E%20RT%5B%22%E6%95%B0%E6%8D%AE%E5%8C%85%E8%B7%B3%E5%9B%9E%20tile%20A%22%5D%0A%20%20RT%20--%3E%20DONE%5B%22%E8%AF%BB%E5%AE%8C%E6%88%90%EF%BC%9A%E5%BB%B6%E8%BF%9F%20%3D%20%E8%B7%B3%E6%95%B0%20%2B%20%E6%8B%A5%E5%A1%9E%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答：一次远程读在 NoC 上是怎么走完往返的。请求逐跳到 home，可能还要发作废并等 ack，数据再跳回来——临界区里等的「可见性」正是这条整链，而不是单程一段。</p><p><span class="marginnote">常见误区：初学者容易以为引入 NoC 只是「带宽变大」。代价是延迟不再恒定：远程读要等包到 home、完成作废 ack 再返回，跳数直接计入临界区长度——锁竞争激烈时，热点路径的跳数就是性能。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选定 mesh 或 torus，下一课拓扑。死锁与维序路由再下一课。多 socket 用另一套物理层。</p><p>后课默认：片上一致性走包交换。链路怎么铺、直径多少，由拓扑决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NoC 用路由器连接 tile，一致性变成包。</li><li>带宽随链路扩展，延迟变跳数与拥塞。</li><li>mesh / torus / fat-tree 是下一课。</li><li>出处：Dally and Towles。</li></ul>',7))])}const N=B(d,[["render",A]]);export{_ as __pageData,N as default};
